export function makeMoonRoomMoveHandlers(): HandlerEntry[] {
  return MOON_MOVES.map((m) => ({
    commandNo: m.commandNo,
    execCheck: (ctx) => {
      const gate = mapCanMove(ctx.state, m.toLocation, ctx.state.master);
      return gate.can ? { ok: true } : { ok: false, reason: { kind: "precondition", message: gate.message ?? "進めない" } };
    },
    handler: (ctx) => {
      const next = cloneGameState(ctx.state);
      setSlotLocation(next.master, m.toLocation);
      advanceTimeTicks(next, 1);
      const activityEvents = pitfallArrivalEvents(next, m.toLocation, ctx.now());
      return {
        state: next,
        events: [...activityEvents, { kind: "NARRATION" as const, timestamp: ctx.now(), text: `%CALLNAME:MASTER% 移動到 ${m.toLocation}。` }],
        outcome: "ok" as const,
      };
    },
  }));
}
